local VERSION='8.0.0'
local ventilators, sedation, liberation = {}, {}, {}
local function uid(prefix)return('%s-%s-%04d'):format(prefix,os.time(),math.random(0,9999))end
exports('ConfigurePrecisionVentilator',function(target,data,actor)data=type(data)=='table'and data or{};local item={id=uid('VENT'),target=target,mode=data.mode or'volume_control',tidalVolume=tonumber(data.tidalVolume)or 450,rate=tonumber(data.rate)or 16,peep=tonumber(data.peep)or 5,fio2=tonumber(data.fio2)or 0.5,actor=actor,updatedAt=os.time()};ventilators[tostring(target)]=item;pcall(function()exports['dpn-medical-core']:SetOrganSupport(target,'ventilator',true,item,actor)end);return true,item end)
exports('SetSedationTarget',function(target,scale,targetScore,actor)local item={id=uid('SED'),target=target,scale=scale or'RASS',targetScore=tonumber(targetScore)or-2,actor=actor,updatedAt=os.time()};sedation[tostring(target)]=item;return true,item end)
exports('AssessLiberationReadiness',function(target)local ok,twin=pcall(function()return exports['dpn-medical-core']:GetPrecisionTwin(target)end);if not ok or type(twin)~='table'then return false end;local ready=twin.pulmonary.pfRatio>=250 and twin.pulmonary.workOfBreathing<45 and twin.hemodynamics.cardiacOutputLpm>=3.5;local item={id=uid('LIB'),target=target,ready=ready,reasons={pfRatio=twin.pulmonary.pfRatio,workOfBreathing=twin.pulmonary.workOfBreathing,cardiacOutput=twin.hemodynamics.cardiacOutputLpm},createdAt=os.time()};liberation[item.id]=item;return ready,item end)
exports('GetICUV8Board',function()return{ventilators=ventilators,sedation=sedation,liberation=liberation,generatedAt=os.time()}end)
CreateThread(function()Wait(3000);pcall(function()exports['dpn-medical-core']:RegisterModule('dpn-medical-icu',VERSION,{'precision_ventilation','sedation_targets','liberation_readiness','critical_care_safety'})end);print('[dpn-medical-icu] v8 ventilation and liberation intelligence active')end)
